css:
.print-format { padding: 0 !important; }
.dacs-walkin { font-family: Arial, sans-serif; font-size: 8pt; margin: 3px 0; padding: 0 6px; text-align: left; }
.dacs-items { width: 100%; font-family: Arial, sans-serif; font-size: 7.5pt; border-collapse: collapse; margin-top: 2px; }
.dacs-items th { font-weight: bold; border-bottom: 1px solid #000; padding: 2px 1px; text-align: center; }
.dacs-items td { padding: 2px 1px; border-bottom: 1px dashed #ccc; vertical-align: top; text-align: center; }
.dacs-items .num { text-align: right; white-space: nowrap; }
/* Item name gets the room; number headers wrap onto two lines instead of widening their columns */
.dacs-items th:first-child, .dacs-items td:first-child { width: 40%; text-align: left; word-break: normal; overflow-wrap: anywhere; }
.dacs-items th.num { white-space: normal; line-height: 1.15; }

html:
{#- POS Invoice Version 2's template on A5 paper (docs/pos-store-scope.md › Print formats): same header (the
    store's own address / GSTIN), columns and totals; blank item rows fill the page bottom. POS Profile › Print Format
    picks it. -#}
{#- page box only when the bill surely fits on one page (item lines — long names count extra — and the terms);
    a longer bill prints as plain flow (docs/print-formats.md › Blank rows) -#}
{%- set fu = namespace(n=0) -%}
{%- for it in doc.items -%}{%- set fu.n = fu.n + 1 + ((it.item_code or '') | length) // 22 -%}{%- endfor -%}
{%- set dacs_fit = fu.n + ((doc.terms or '') | striptags | length) // 150 <= 12 -%}
<style>
/* PDF page size and margins (wkhtmltopdf reads them from this rule, frappe.utils.pdf); @page for the browser's print */
.print-format { margin-top: 10mm; margin-bottom: 10mm; page-size: A5; }
@media print { body .print-format { margin: 0 !important; } }
@page { size: A5; margin: 10mm; }
.dacs-items { table-layout: fixed; }
.dacs-items th:first-child, .dacs-items td:first-child { width: auto; }
.dacs-fill-wrap { display: none; }
.dacs-nodisc .dacs-d { display: none; }
.dacs-fill-wrap .dacs-items { margin-top: 0; }
/* a bill that ends at the page bottom: no empty sheet after it */
.print-format .page-break:last-child, .print-format > div:last-child { page-break-after: auto !important; }
{% if dacs_fit %}
/* Page box: the bill is a vertical box of the printable height; the items part stretches and its blank rows — a
   clipped table of empty rows after the items — fill the space left */
.pos-page { display: -webkit-box; -webkit-box-orient: vertical; height: 188mm; /* dacs page height */ }
.dacs-items-box { -webkit-box-flex: 1; display: -webkit-box; -webkit-box-orient: vertical; }
.dacs-fill-wrap { -webkit-box-flex: 1; height: 0; overflow: hidden; display: block !important; }
{% endif %}
</style>
{# Store address comes from the Address linked to the bill's warehouse (POS Profile › Warehouse), so each store prints its own address #}
{% set store_wh = doc.set_warehouse or (frappe.db.get_value("POS Profile", doc.pos_profile, "warehouse") if doc.pos_profile else None) %}
{% set address_doc = None %}
{% if store_wh %}
    {% set wh_address = frappe.get_all("Address", filters={"link_doctype": "Warehouse", "link_name": store_wh, "disabled": 0}, fields=["name"], limit=1) %}
    {% if wh_address %}{% set address_doc = frappe.get_doc("Address", wh_address[0].name) %}{% endif %}
{% endif %}

<div class="pos-page">
<div style="font-family: Arial, sans-serif; line-height: 1; margin: 0; padding: 0; color: #000;">

    <!-- Header: logo | company + store address + contacts | GST / PAN / MSME / Landline -->
    <table style="width:100%; border-collapse:collapse;">
        <tr>
            <td style="width:62px; vertical-align:middle; padding:2px 6px 2px 0;">
                <img src="/files/Dacs inc Logo.jpeg" style="width:56px; height:56px; object-fit:contain;">
            </td>
            <td style="vertical-align:middle; padding:2px 0;">
                <div style="font-size:12pt; font-weight:bold;">{{ doc.company }}</div>
                <div style="font-size:7.5pt; line-height:1.3; margin-top:2px;">
                    {% if address_doc %}
                        {{ address_doc.address_line1 or "" }}{% if address_doc.address_line2 %}, {{ address_doc.address_line2 }}{% endif %}, {{ address_doc.city or "" }} - {{ address_doc.pincode or "" }}<br>
                    {% endif %}
                    <strong>Email:</strong> customercare@dacsinc.in &nbsp;|&nbsp; <strong>Web:</strong> online.www.dacsincstore.in
                </div>
            </td>
            <td style="vertical-align:middle; text-align:right; font-size:7.5pt; line-height:1.4; white-space:nowrap; padding:2px 0 2px 6px;">
                <strong>G.S.T. :</strong> {{ (address_doc and address_doc.gstin) or "29AAIFD5710C1ZQ" }}<br>
                <strong>PAN :</strong> AAIFD5710C<br>
                <strong>MSME No :</strong> UDYAM-KR-03-00310188<br>
                <strong>Landline :</strong> 080-41206892
            </td>
        </tr>
    </table>

    <!-- Thin Hairline Divider -->
    <div style="border-top: 1px solid #000; margin: 1px 0;"></div>

    <!-- Row 3: Transaction Info (Primary focus) -->
    <table style="width:100%; font-size: 8.5pt; border-collapse: collapse;">
        <tr>
            <td style="text-align:left; width:50%;">
                <strong>Inv:</strong> {{ doc.name }}
            </td>
            <td style="text-align:right; width:50%;">
                <strong>Dt:</strong> {{ frappe.utils.formatdate(doc.posting_date) }} 
                {% if doc.posting_time %}
                    {{ frappe.utils.format_time(doc.posting_time) }}
                {% endif %}
            </td>
        </tr>
    </table>

    <!-- Final Border before items table -->
    <div style="border-top: 1px solid #000; margin-top: 1px;"></div>
</div>

<!-- Walk-in customer (POS Invoice › Walk-in Name / Mobile), only when filled -->
{% if doc.custom_walkin_name or doc.custom_walkin_mobile %}
<div class="dacs-walkin">
    {% if doc.custom_walkin_name %}<strong>Customer:</strong> {{ doc.custom_walkin_name }}{% endif %}
    {% if doc.custom_walkin_name and doc.custom_walkin_mobile %}&nbsp;&nbsp;|&nbsp;&nbsp;{% endif %}
    {% if doc.custom_walkin_mobile %}<strong>Customer No:</strong> {{ doc.custom_walkin_mobile }}{% endif %}
</div>
<div style="border-top: 1px solid #000;"></div>
{% endif %}

<!-- Items: Price List Rate and Discount Amount only when the bill has a discount -->
{% set disc = namespace(on=false) %}
{% for i in doc.items %}
    {% if (i.discount_amount or 0) | float > 0.001 or ((i.price_list_rate or 0) | float - (i.rate or 0) | float) > 0.001 %}{% set disc.on = true %}{% endif %}
{% endfor %}
<div class="dacs-items-box">
<table class="dacs-items{{ '' if disc.on else ' dacs-nodisc' }}">
    <colgroup><col style="width:34%;"><col style="width:10%;"><col style="width:6%;"><col class="dacs-d" style="width:13%;"><col class="dacs-d" style="width:13%;"><col style="width:12%;"><col style="width:12%;"></colgroup>
    <thead>
        <tr>
            <th style="text-align:left;">{{ _("Item") }}</th>
            <th>{{ _("HSN") }}</th>
            <th class="num">{{ _("Qty") }}</th>
            {% if disc.on %}
            <th class="num">{{ _("Price List Rate") }}</th>
            <th class="num">{{ _("Discount Amount") }}</th>
            {% endif %}
            <th class="num">{{ _("Rate") }}</th>
            <th class="num">{{ _("Amount") }}</th>
        </tr>
    </thead>
    <tbody>
        {% for i in doc.items %}
        <tr>
            <td style="text-align:left;">{{ i.item_code }}</td>
            <td>{{ i.gst_hsn_code or "" }}</td>
            <td class="num">{{ (i.qty | int) if i.qty == (i.qty | int) else i.qty }}</td>
            {% if disc.on %}
            <td class="num">{{ frappe.utils.fmt_money(i.price_list_rate, currency=doc.currency) }}</td>
            <td class="num">{{ frappe.utils.fmt_money(i.discount_amount, currency=doc.currency) if i.discount_amount else "" }}</td>
            {% endif %}
            <td class="num">{{ frappe.utils.fmt_money(i.rate, currency=doc.currency) }}</td>
            <td class="num">{{ frappe.utils.fmt_money(i.amount, currency=doc.currency) }}</td>
        </tr>
        {% endfor %}
    </tbody>
</table>
<div class="dacs-fill-wrap">
<table class="dacs-items{{ '' if disc.on else ' dacs-nodisc' }}">
    <colgroup><col style="width:34%;"><col style="width:10%;"><col style="width:6%;"><col class="dacs-d" style="width:13%;"><col class="dacs-d" style="width:13%;"><col style="width:12%;"><col style="width:12%;"></colgroup>
    <tbody>{%- for r in range(60) %}<tr>{%- for c in range(7 if disc.on else 5) %}<td>&nbsp;</td>{%- endfor %}</tr>{%- endfor %}</tbody>
</table>
</div>
</div>

<!-- 1. Logic -->
{% set ns = namespace(line_dis=0.0) %}
{% for i in doc.items %}{% set ns.line_dis = ns.line_dis + (i.discount_amount | float or 0) %}{% endfor %}
{% set ov_dis = doc.discount_amount | float or 0 %}
{% set total_qty = doc.items | sum(attribute='qty') %}
{% set pay_sum = doc.payments | sum(attribute='amount') %}

<div style="font-family: Arial, sans-serif; border-top: 1px solid #000; line-height: 1; margin-top: 2px; font-size: 7.5pt;">

    <!-- 1. Qty & Payment (Single Thin Line) -->
    <div style="border-bottom: 1px dashed #ccc; margin-top:2px;padding: 5px 0; overflow: hidden;">
        <span><strong>Qty:</strong> {{ total_qty }}</span>
        {% if pay_sum > 0 %}
        <span style="float: right;"><strong>Pay:</strong> {% for p in doc.payments if p.amount > 0 %}{{ p.mode_of_payment.split('-')[0].strip() }} ({{ frappe.utils.fmt_money(p.amount, currency=doc.currency) }}){{ "," if not loop.last }}{% endfor %}</span>
        {% endif %}
    </div>

    <!-- 2. MAIN SECTION: Side-by-Side (Saves vertical space) -->
    <table style="width: 100%; border-collapse: collapse; table-layout: fixed; margin-top: 2px;">
        <tr>
            <!-- LEFT: TAX SUMMARY -->
            <td style="width: 65%; vertical-align: top; padding-right: 5px; font-size: 7pt;">
                <div style="font-weight: bold; text-decoration: underline; margin-bottom: 1px;">TAX HSN/SAC</div>
                <div style="line-height: 0.8;">{{ doc.gst_breakup_table or "" }}</div>
            </td>

            <!-- RIGHT: TOTALS (Condensed) -->
            <td style="width: 35%; vertical-align: top; border-left: 1px solid #eee; padding-left: 5px;">
                <table style="width: 100%; border-collapse: collapse; font-size: 8pt;">
                    <tr><td>Gross Total</td><td style="text-align:right;">{{ frappe.utils.fmt_money(doc.net_total + ns.line_dis, currency=doc.currency) }}</td></tr>

                    {% if ns.line_dis > 0.01 %}
                    <tr style="color:red;"><td>Item Disc (-)</td><td style="text-align:right;">-{{ frappe.utils.fmt_money(ns.line_dis, currency=doc.currency) }}</td></tr>
                    {% endif %}

                    <tr style="font-weight:bold; border-top:1px solid #eee;"><td>Taxable</td><td style="text-align:right;">{{ frappe.utils.fmt_money(doc.net_total, currency=doc.currency) }}</td></tr>

                    <tr><td>Total Tax (+)</td><td style="text-align:right;">{{ frappe.utils.fmt_money(doc.total_taxes_and_charges, currency=doc.currency) }}</td></tr>

                    {% if ov_dis > 0.01 %}
                    <tr style="color:red;"><td>Bill Disc (-)</td><td style="text-align:right;">-{{ frappe.utils.fmt_money(ov_dis, currency=doc.currency) }}</td></tr>
                    {% endif %}

                    <tr style="background:#f2f2f2; border:1px solid #000; font-weight:bold; font-size: 9pt;">
                        <td style="padding:1px;">TOTAL ₹</td>
                        <td style="text-align:right; padding:1px;">{{ frappe.utils.fmt_money(doc.grand_total, currency=doc.currency) }}</td>
                    </tr>
                </table>
            </td>
        </tr>
    </table>

    <!-- 3. TERMS & THANK YOU (Minimized) -->
    <div style="margin-top: 2px; border-top: 1px solid #eee; font-size: 6.5pt; color: #555;">
        <!-- 3. FULL TERMS & CONDITIONS (Fine Print Style) -->
    {% if doc.terms %}
    <div style="border-top: 1px solid #000; margin-top: 1px; ">
        <div style="font-size: 5.5pt; line-height: 1; color: #222; text-align: justify;">
            <strong style="font-size: 7pt; color: #000; text-decoration: underline;">Terms & Conditions:</strong>
            <div class="terms-wrapper" style="margin-top: 1px;">
                {# Using a wrapper to force child elements like <p> to have zero margin #}
                <style>
                    .terms-wrapper p, .terms-wrapper div, .terms-wrapper br { margin: 0 !important; padding: 0 !important; }
                </style>
                {{ doc.terms | safe }}
            </div>
        </div>
    </div>
    {% endif %}

    <!-- 4. THANK YOU -->
    <div style="text-align: center; font-weight: bold; font-size: 7.5pt; color: #000; margin-top: 2px; border-top: 1px dashed #ccc; padding-top: 1px;">
        *** Thank You - Visit Again ***
    </div>
    </div>
</div>
</div>
